#include <bits/stdc++.h>
using namespace std;
typedef __int128 i128;

// Coordinates are fixed-point integers scaled by S = 10^15, so the ternary search
// runs exactly; the 10^-15 grid is far finer than the required 10^-6 rounding.
const i128 S = (i128)1000000000000000LL;

string toStr(i128 v) {
    if (v == 0) return "0";
    string s;
    while (v > 0) { s += char('0' + (int)(v % 10)); v /= 10; }
    reverse(s.begin(), s.end());
    return s;
}

int main() {
    int q;
    cin >> q;
    string out;
    while (q--) {
        long long a, b, c, l, r;
        cin >> a >> b >> c >> l >> r;
        i128 left = l * S, right = r * S;
        for (int it = 0; it < 160; it++) {
            i128 x = left + (right - left) / 3, y = right - (right - left) / 3;
            // for x < y: f(x) < f(y)  <=>  (x - y)(a(x + y) + b) < 0  <=>  a(x + y) + b > 0
            if (a * (x + y) + b * S > 0) right = y;
            else left = x;
        }
        // midpoint (left + right) / 2 rounded half up to micro-units: divide by 2 * 10^9
        i128 num = left + right, den = 2000000000;
        bool neg = num < 0;
        if (neg) num = -num;
        i128 units = num / den;
        if (2 * (num % den) >= den) units++;
        string part = to_string((long long)(units % 1000000));
        out += (neg && units ? "-" : "") + toStr(units / 1000000) + "." + string(6 - part.size(), '0') + part + "\n";
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.math.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = sc.nextInt();
        MathContext mc = new MathContext(60);
        BigDecimal three = BigDecimal.valueOf(3), two = BigDecimal.valueOf(2);
        StringBuilder sb = new StringBuilder();
        while (q-- > 0) {
            BigDecimal a = new BigDecimal(sc.next()), b = new BigDecimal(sc.next()), c = new BigDecimal(sc.next());
            BigDecimal left = new BigDecimal(sc.next()), right = new BigDecimal(sc.next());
            for (int it = 0; it < 160; it++) {
                BigDecimal third = right.subtract(left, mc).divide(three, mc);
                BigDecimal x = left.add(third, mc), y = right.subtract(third, mc);
                if (f(a, b, c, x, mc).compareTo(f(a, b, c, y, mc)) < 0) right = y;
                else left = x;
            }
            BigDecimal point = left.add(right, mc).divide(two, mc);
            sb.append(point.setScale(6, RoundingMode.HALF_UP).toPlainString()).append('\n');
        }
        System.out.print(sb);
    }

    // f(x) = (a x + b) x + c with 60 significant digits
    static BigDecimal f(BigDecimal a, BigDecimal b, BigDecimal c, BigDecimal x, MathContext mc) {
        return a.multiply(x, mc).add(b, mc).multiply(x, mc).add(c, mc);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/big"
	"os"
	"strings"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	var q int
	fmt.Fscan(in, &q)
	// Coordinates are fixed-point integers scaled by S = 10^15, so the ternary search
	// runs exactly; the 10^-15 grid is far finer than the required 10^-6 rounding.
	S := big.NewInt(1000000000000000)
	three := big.NewInt(3)
	half := big.NewInt(2000000000)
	million := big.NewInt(1000000)
	third, x, y, t, bs := new(big.Int), new(big.Int), new(big.Int), new(big.Int), new(big.Int)
	for ; q > 0; q-- {
		var a, b, c, l, r int64
		fmt.Fscan(in, &a, &b, &c, &l, &r)
		left := new(big.Int).Mul(big.NewInt(l), S)
		right := new(big.Int).Mul(big.NewInt(r), S)
		A := big.NewInt(a)
		bs.Mul(big.NewInt(b), S)
		for it := 0; it < 160; it++ {
			third.Quo(t.Sub(right, left), three)
			x.Add(left, third)
			y.Sub(right, third)
			// for x < y: f(x) < f(y)  <=>  (x - y)(a(x + y) + b) < 0  <=>  a(x + y) + b > 0
			t.Add(x, y)
			t.Mul(t, A)
			if t.Add(t, bs).Sign() > 0 {
				right.Set(y)
			} else {
				left.Set(x)
			}
		}
		// midpoint (left + right) / 2 rounded half up to micro-units: divide by 2 * 10^9
		num := new(big.Int).Add(left, right)
		neg := num.Sign() < 0
		num.Abs(num)
		units, rem := new(big.Int).QuoRem(num, half, new(big.Int))
		if rem.Lsh(rem, 1).Cmp(half) >= 0 {
			units.Add(units, big.NewInt(1))
		}
		if neg && units.Sign() > 0 {
			w.WriteByte('-')
		}
		whole, part := new(big.Int).QuoRem(units, million, new(big.Int))
		ps := part.String()
		w.WriteString(whole.String() + "." + strings.Repeat("0", 6-len(ps)) + ps + "\n")
	}
}
